{"content":"<#
.SYNOPSIS
    Core service-management functions for the RAZOR Service Manager.
.DESCRIPTION
    Wraps Get-Service / Start-Service / Stop-Service with structured output,
    logging, and a safety allow-list so the web UI can only touch approved
    services. Imported by the API layer (ApiServer.ps1).
#>

Import-Module "$PSScriptRoot/Logger.ps1" -Force

$script:AllowListPath = "$PSScriptRoot/../config/allowed-services.json"

function Get-AllowedServices {
    <#.SYNOPSIS Load the allow-list of service names the UI may control.#>
    if (-not (Test-Path $script:AllowListPath)) {
        Write-Log -Level WARN -Message "Allow-list not found at $script:AllowListPath"
        return @()
    }
    $json = Get-Content $script:AllowListPath -Raw | ConvertFrom-Json
    return $json.services
}

function Test-ServiceAllowed {
    param([Parameter(Mandatory)][string]$Name)
    $allowed = Get-AllowedServices
    return $allowed -contains $Name
}

function Get-ServiceStatus {
    <#.SYNOPSIS Return structured status for one or all allowed services.#>
    param([string]$Name)

    $targets = if ($Name) { @($Name) } else { Get-AllowedServices }
    $result = foreach ($svc in $targets) {
        try {
            $s = Get-Service -Name $svc -ErrorAction Stop
            [pscustomobject]@{
                Name      = $s.Name
                Display   = $s.DisplayName
                Status    = $s.Status.ToString()
                StartType = $s.StartType.ToString()
            }
        } catch {
            Write-Log -Level ERROR -Message "Get-ServiceStatus failed for $svc : $_"
            [pscustomobject]@{ Name = $svc; Status = "NotFound" }
        }
    }
    return $result
}

function Start-ManagedService {
    param([Parameter(Mandatory)][string]$Name)
    if (-not (Test-ServiceAllowed -Name $Name)) {
        Write-Log -Level WARN -Message "Blocked start of non-allowed service: $Name"
        throw "Service '$Name' is not in the allow-list."
    }
    Start-Service -Name $Name
    Write-Log -Level INFO -Message "Started service $Name"
    return Get-ServiceStatus -Name $Name
}

function Stop-ManagedService {
    param([Parameter(Mandatory)][string]$Name)
    if (-not (Test-ServiceAllowed -Name $Name)) {
        Write-Log -Level WARN -Message "Blocked stop of non-allowed service: $Name"
        throw "Service '$Name' is not in the allow-list."
    }
    Stop-Service -Name $Name -Force
    Write-Log -Level INFO -Message "Stopped service $Name"
    return Get-ServiceStatus -Name $Name
}

function Restart-ManagedService {
    param([Parameter(Mandatory)][string]$Name)
    Stop-ManagedService -Name $Name | Out-Null
    Start-Sleep -Seconds 1
    return Start-ManagedService -Name $Name
}

